package com.logistics.fleet.controller;

import com.logistics.fleet.dto.GpsCoordinate;
import com.logistics.fleet.service.ReactiveFleetAuthService;
import com.logistics.fleet.service.ReactiveGpsService;
import org.springframework.http.MediaType;
import org.springframework.http.codec.ServerSentEvent;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import reactor.core.publisher.Flux;

@RestController
@RequestMapping("/fleet/vehicles")
public class FleetTrackingController {

    private final ReactiveGpsService gpsService;
    private final ReactiveFleetAuthService authService;

    public FleetTrackingController(ReactiveGpsService gpsService, ReactiveFleetAuthService authService) {
        this.gpsService = gpsService;
        this.authService = authService;
    }

    @GetMapping(value = "/{vehicleId}/live-track", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public Flux<ServerSentEvent<GpsCoordinate>> streamVehicleCoordinates(
            @PathVariable String vehicleId,
            Authentication authentication) {
        return authService.verifyVehicleCarrierAccess(vehicleId, authentication.getName())
                .flatMapMany(authorized -> {
                    if (!authorized) {
                        return Flux.error(new AccessDeniedException("Access to vehicle GPS stream forbidden"));
                    }
                    return gpsService.getCoordinateStream(vehicleId)
                            .map(coord -> ServerSentEvent.<GpsCoordinate>builder()
                                    .event("gps-ping")
                                    .data(coord)
                                    .build());
                });
    }
}
